{
    dev = &g_realtek_dev[devidx].dev;
    tx_queue = &g_realtek_dev[devidx].tx_buff_queue;
设备管理：
  - 设备0: STA模式（客户端），连接AP
  - 设备1: AP模式（热点），创建WiFi网络
  - 每个设备有独立的发送队列和缓冲区管理
6.5.4 队列遍历准备
frame_phead = get_list_head(tx_queue);      // 获取队列头指针
frame_plist = get_next(frame_phead);        // 获取第一个数据包节点
队列结构：
  - 使用链表结构管理待发送的数据包
  - 每个节点包含数据包信息和指向下一个节点的指针
6.5.5 数据包处理循环
while (1)
{
    // 临界区保护开始
    rtw_enter_critical_bh(&tx_queue->lock, &irqL);

    // 检查是否到达队列末尾
    if (rtw_end_of_queue_search(frame_phead, frame_plist) == _TRUE)
    {
        rtw_exit_critical_bh(&tx_queue->lock, &irqL);
        break;  // 队列遍历完成，退出内层循环
    }

    rtw_exit_critical_bh(&tx_queue->lock, &irqL);
    // 临界区保护结束
队列遍历机制：
  - 使用临界区保护确保队列操作的原子性
  - 安全地检查队列状态，防止并发访问冲突
  - 遍历整个队列直到处理完所有数据包
6.5.6 网络接口状态检查
save_and_cli(&irqL1);  // 保存并禁用中断
if (rltk_wlan_check_isup(devidx)) {  // 检查网络接口是否启动
    rltk_wlan_tx_inc(devidx);       // 接口启动，增加发送计数
} else {
    // 接口关闭时的清理操作
    DBG_INFO("netif is DOWN");
    restore_flags(irqL1);  // 恢复中断状态

    // 清空整个发送队列
    rtw_enter_critical_bh(&tx_queue->lock, &irqL);
    frame_phead = get_list_head(tx_queue); 

    while (rtw_is_list_empty(frame_phead) == _FALSE)  // 队列非空时循环
    {
        frame_plist = get_next(frame_phead);          // 获取下一个节点
        tx_pkt = LIST_CONTAINOR(frame_plist, struct realtek_pkt_list, list); 

        // 从队列中删除节点
        rtw_list_delete(&tx_pkt->list);

        // 释放网络数据包资源
        netpkt_free(dev, tx_pkt->pkt, NETPKT_TX);

        // 释放包列表结构内存
        free(tx_pkt);          
    }

    // 重置空闲发送计数
    g_realtek_dev[devidx].free_tx_count = 512; 
    rtw_exit_critical_bh(&tx_queue->lock, &irqL);
    break;  // 退出当前设备处理
}
restore_flags(irqL1);  // 恢复中断状态
状态检查逻辑：
  - 接口启动: 正常处理数据包发送
  - 接口关闭: 执行清理操作，释放所有资源
6.5.7 数据包提取和准备
// 重新进入临界区获取数据包信息
rtw_enter_critical_bh(&tx_queue->lock, &irqL);
// 从链表节点获取数据包结构
tx_pkt = LIST_CONTAINOR(frame_plist, struct realtek_pkt_list, list);  
// 移动到下一个节点，为下次循环准备
frame_plist = get_next(frame_plist);       
// 获取数据包长度
len = netpkt_getdatalen(dev, tx_pkt->pkt);
rtw_exit_critical_bh(&tx_queue->lock, &irqL);
6.5.8 数据包信息获取
  - 安全地从队列中提取数据包信息
  - 获取数据长度用于后续缓冲区分配
  - 准备发送所需的所有参数
6.5.9 SKB缓冲区分配
// 分配SKB缓冲区用于硬件发送
skb = rltk_wlan_alloc_skb(len);
// 临界区保护分配结果检查
rtw_enter_critical_bh(&tx_queue->lock, &irqL);
if (!skb)  // SKB分配失败处理
{
    rtw_exit_critical_bh(&tx_queue->lock, &irqL);

    // 减少发送计数
    save_and_cli(&irqL1);
    rltk_wlan_tx_dec(devidx);           
    restore_flags(irqL1);

    // 短暂休眠后重试
    rtw_msleep_os(1);
    continue;  // 继续处理下一个数据包
}
缓冲区管理：
  - SKB是Linux网络栈中的标准缓冲区结构
  - 分配失败时进行重试，避免数据丢失
  - 合理的错误恢复机制
6.5.10 队列管理和内存释放
// 从队列中删除已处理的数据包节点
rtw_list_delete(&tx_pkt->list);
// 增加空闲发送计数
g_realtek_dev[devidx].free_tx_count++; 
rtw_exit_critical_bh(&tx_queue->lock, &irqL);
队列维护：
  - 及时从队列中移除已处理的数据包
  - 更新资源计数，反映可用资源状态
  - 确保队列管理的正确性
6.5.11 数据拷贝和发送
// 将数据从网络包拷贝到SKB缓冲区
netpkt_copyout(dev, skb->tail, tx_pkt->pkt, len, 0);
// 更新SKB的数据长度
skb_put(skb, len);
// 调用底层驱动发送数据包
rltk_wlan_send_skb(devidx, skb);
数据发送核心：
  - 执行实际的数据拷贝操作
  - 准备SKB缓冲区供硬件使用
  - 调用硬件相关的发送函数
6.5.12 资源清理和状态更新
// 释放原始网络数据包资源
netpkt_free(dev, tx_pkt->pkt, NETPKT_TX);
// 释放包列表结构内存
free(tx_pkt);
// 减少发送计数
save_and_cli(&irqL1);
rltk_wlan_tx_dec(devidx);
restore_flags(irqL1);
// 通知协议栈发送完成
netdev_lower_txdone(dev);
资源管理：
  - 及时释放所有分配的内存资源
  - 更新发送状态计数器
  - 通知上层协议栈发送完成事件
7. WiFi 打开流程
WiFi_on函数是Realtek WiFi驱动的核心启动入口，具有以下特点：
  1. 完整性: 涵盖从硬件初始化到协议栈集成的完整流程
  2. 可靠性: 完善的错误处理和资源管理机制
  3. 灵活性: 支持多种工作模式和设备配置
  4. 安全性: 线程安全和超时保护确保系统稳定
  5. 可扩展性: 条件编译支持不同的协议栈配置
这个函数确保了Realtek WiFi模块能够在各种模式下正确启动并集成到NuttX网络系统中。
WiFi_on(mode) 入口
    ↓
检查WiFi是否已在运行 → 是 → 直接返回
    ↓ 否
初始化事件回调系统（单次）
    ↓
设置工作模式和设备数量
    ↓
循环初始化每个WiFi设备（rltk_wlan_init）
    ↓ 失败 → 返回错误
    ↓ 成功
循环启动每个WiFi设备（rltk_wlan_start）
    ↓ 失败 → 执行反初始化 → 返回错误
    ↓ 成功
等待WiFi运行状态就绪（超时20秒）
    ↓ 超时 → 返回错误
    ↓ 就绪
设置国家代码和射频参数
    ↓
启动网络协议栈接口（条件编译）
    ↓
返回成功（1）
7.1.1 初始检查和变量声明
int ret = 1;
int timeout = 20;
int idx;
int devnum = 1;
static int event_init = 0;
if(rltk_wlan_running(WLAN0_IDX)) {
    DBG_INFO("WiFi is already running");
    return 1;
}
初始检查：
  - 运行状态检测: 检查WiFi是否已经在运行，避免重复初始化
  - 超时设置: 设置20秒的初始化超时时间
  - 设备数量: 默认1个设备，STA+AP模式时为2个
7.1.2 事件回调初始化
if(event_init == 0){
    init_event_callback_list();
    event_init = 1;
}
事件系统初始化：
  - 单次初始化: 使用静态变量确保只初始化一次
  - 回调列表: 初始化WiFi事件回调机制
  - 事件支持: 为连接状态、扫描结果等事件提供支持
7.1.3 模式设置和设备数量确定
WiFi_mode = mode;
if(mode == RTW_MODE_STA_AP)
    devnum = 2;
模式配置：
  - STA模式: 客户端模式，连接AP（1个设备）
  - AP模式: 热点模式，创建网络（1个设备）
  - STA+AP模式: 同时支持客户端和热点（2个设备）
7.1.4 WiFi初始化循环
DBG_INFO("Initializing WiFi ...");
for(idx=0; idx<devnum; idx++){
    ret = rltk_wlan_init(idx, mode);
    if(ret <0)
        return ret;
}
设备初始化：
  - 循环初始化: 对每个WiFi设备执行初始化
  - 底层驱动调用: rltk_wlan_init执行硬件相关初始化，rltk_wlan_init被厂家封装在静态库中，不做讨论
  - 错误处理: 任一设备初始化失败则立即返回
7.1.5  WiFi启动循环
for(idx=0; idx<devnum; idx++){
    device_mutex_lock(RT_DEV_LOCK_WLAN);
    ret = rltk_wlan_start(idx);
    if(ret == 0) _WiFi_is_on = 1;
    device_mutex_unlock(RT_DEV_LOCK_WLAN);
    if(ret <0){
        DBG_INFO("ERROR: Start WiFi Failed!");
        rltk_wlan_deinit();
        return ret;
    }
}
设备启动关键步骤：
  - 互斥锁保护: 使用设备互斥锁确保线程安全
  - 启动调用: rltk_wlan_start启动WiFi硬件
  - 状态标记: 成功启动后设置_WiFi_is_on标志
  - 错误回滚: 启动失败时执行反初始化清理资源
7.1.6 启动状态检测和超时处理
while(1) {
    if(rltk_wlan_running(devnum-1)) {
        DBG_INFO("WiFi initialized\n");
        WiFi_set_country_code();
        break;
    }
    if(timeout == 0) {
        DBG_INFO("ERROR: Init WiFi timeout!");
        break;
    }
    rtw_msleep_os(1000);
    timeout --;
}
状态监控机制：
- 持续检测: 循环检查WiFi运行状态
- 超时保护: 20秒超时防止无限等待
- 国家代码设置: 启动成功后配置射频参数
- 渐进式等待: 每秒检查一次状态
7.2 网络协议栈集成
#if CONFIG_LWIP_LAYER
#if defined(CONFIG_PLATFOMR_CUSTOMER_RTOS)
//TODO
#else
netif_set_up(&xnetif[0]);
if(mode == RTW_MODE_AP) 
    netif_set_link_up(&xnetif[0]);
else if(mode == RTW_MODE_STA_AP) {
    netif_set_up(&xnetif[1]);                
    netif_set_link_up(&xnetif[1]);
}
#endif
#endif
协议栈集成：
- 条件编译: 仅在启用LWIP协议栈时执行
- 网络接口启动: 启动对应的网络接口
- 链路状态设置: 设置链路状态为UP
- 多设备支持: STA+AP模式时启动两个网络接口
几个关键函数调用说明(静态库)
