    wapi实际是一个通用命令，通过命令关键字，如"scan","psk","mode"等，结合后面ifname字段 (wlan0).
//apps/wireless/wapi/src/wapi.c
struct wapi_command_s
{
  FAR const char *name; //命令名称
  uint8_t minargs;      //需要提供的最小参数个数
  uint8_t maxargs;      //需要提供的最大参数个数
  wapi_cmd_t handler;   //具体执行的函数
};

...

static const struct wapi_command_s g_wapi_commands[] =
{
  {"help",         0, 0, NULL},
  {"show",         1, 1, wapi_show_cmd},
  {"scan",         1, 2, wapi_scan_cmd},
...
};
    利用命令关键字，如"scan","psk","mode"，转到对应的执行函数。所有执行函数的运行原理基本一致，这里以wapi_scan_cmd说明:
int main(int argc, FAR char *argv[])
{
...
  cmdname = argv[1];

  struct wapi_command_s *wapicmd = NULL;
  for (i = 0; i < nitems(g_wapi_commands); i++)
    {
      FAR const struct wapi_command_s *cmd = &g_wapi_commands[i];
      if (strcmp(cmdname, cmd->name) == 0)
        {
          wapicmd = cmd;
          break;
        }
    }

  if (wapicmd == NULL)
    {
      WAPI_ERROR("ERROR: Unsupported command: %s\n", cmdname);
      wapi_showusage(argv[0], EXIT_FAILURE);
    }

  if (wapicmd->maxargs + 2 < argc)
    {
      WAPI_ERROR("ERROR: Garbage at end of command ignored\n");
    }
  else if (wapicmd->minargs + 2 > argc)
    {
      WAPI_ERROR("ERROR: Missing required command options: %s\n",
                 cmdname);
      wapi_showusage(argv[0], EXIT_FAILURE);
    }

  /* Special case the help command which has no arguments, no handler,
   * and does not need a socket.
   */

  if (wapicmd->handler == NULL)
    {
      wapi_showusage(argv[0], EXIT_SUCCESS);
    }

  /* Create a communication socket */

  sock = wapi_make_socket();
  if (sock < 0)
    {
      WAPI_ERROR("ERROR: wapi_make_socket() failed: %d\n", sock);
      return EXIT_FAILURE;
    }

  ret = wapicmd->handler(sock, argc - 2, argc == 2 ? NULL : &argv[2]);
  if (ret < 0)
    {
      WAPI_ERROR("ERROR: Process command (%s) failed.\n", cmdname);
    }

  /* Close communication socket */

  close(sock);
  return ret;
}
    wapi通过传递的argv[1]获取cmdname的值scan匹配g_wapi_commands找到对应的wapicmd，同时wapi_make_socket创建一个内部通信的socket，用于给后面的handler做套接字。找到对应的wapicmd也就找到了对应的这个结构里的handler，也就是wapi_scan_cmd。
static int wapi_scan_cmd(int sock, int argc, FAR char **argv)
{
  /* Start scan 这里的argv[0]指代用户输入的ifname，因为这个handle支持最大2个参数，所以ifname后面可以跟指定的ssid，没有则表示扫描周围所有热点 */
  ret = wapi_escan_init(sock, argv[0], IW_SCAN_TYPE_ACTIVE, essid);
  return wapi_scan_results_cmd(sock, 1, argv);
}

struct iwreq
{
  char ifr_name[IFNAMSIZ];  /* Interface name, e.g. "eth0" */
  union iwreq_data u;       /* Data payload */
};
union iwreq_data
{
  char name[IFNAMSIZ];      /* Network interface name */
  struct iw_point essid;    /* Extended network name */
  struct iw_param nwid;     /* Network id (or domain - the cell) */
  struct iw_freq freq;      /* frequency or channel :
                             * 0-1000 = channel
                             * > 1000 = frequency in Hz */
  struct iw_param sens;     /* signal level threshold */
  struct iw_param bitrate;  /* default bit rate */
  struct iw_param txpower;  /* default transmit power */
  struct iw_param rts;      /* RTS threshold threshold */
  struct iw_param frag;     /* Fragmentation threshold */
  uint32_t mode;            /* Operation mode */
  struct iw_param retry;    /* Retry limits & lifetime */

  struct iw_point encoding; /* Encoding stuff : tokens */
  struct iw_param power;    /* PM duration/timeout */
  struct iw_quality qual;   /* Quality part of statistics */

  struct sockaddr ap_addr;  /* Access point address */
  struct sockaddr addr;     /* Destination address (hw/mac) */

  struct iw_param param;    /* Other small parameters */
  struct iw_point data;     /* Other large parameters */
};

//wapi_escan_init----->wapi_escan_channel_init
int wapi_escan_channel_init(int sock, FAR const char *ifname,
                           uint8_t scan_type, FAR const char *essid,
                           uint8_t *channels, int num_channels)
{
  struct iw_scan_req req;
  struct iwreq wrq =
  {
  };

  size_t essid_len;
  int ret;
  int i;

  memset(&req, 0, sizeof(req));

  if (essid && (essid_len = strlen(essid)) > 0)
    {
      req.essid_len    = essid_len;
      memcpy(req.essid, essid, essid_len);
      wrq.u.data.flags = IW_SCAN_THIS_ESSID;
    }

  if (channels && num_channels > 0)
    {
      req.num_channels = num_channels;
      for (i = 0; i < num_channels; i++)
        {
          req.channel_list[i].m = channels[i];
        }
    }

  req.scan_type       = scan_type;
  req.bssid.sa_family = ARPHRD_ETHER;
  memset(req.bssid.sa_data, 0xff, IFHWADDRLEN);
  wrq.u.data.pointer  = (caddr_t)&req;
  wrq.u.data.length   = sizeof(req);

  strlcpy(wrq.ifr_name, ifname, IFNAMSIZ);
  ret = ioctl(sock, SIOCSIWSCAN, (unsigned long)((uintptr_t)&wrq));
  if (ret < 0)
    {
      int errcode = errno;
      WAPI_IOCTL_STRERROR(SIOCSIWSCAN, errcode);
      ret = -errcode;
    }

  return ret;
}

    命令的实质是构建一个struct iwreq结构体结构，通过ioctl发给创建ifname ,也就是wlan0的创建者。前文realtek_netdev_init章节，里面的netdev_lower_register负责注册网卡名。
struct iwreq的iwreq_data是一个枚举变量，根据具体的命令，发送对应的数据结构。具体可以参考nuttx/include/nuttx/wireless/wireless.h:513
