6. 在openvela中适配蓝牙驱动
openvela蓝牙支持丰富的设备驱动模型，支持标准的BTH4和BTH5协议，支持双协议栈场景和轻量级HCI场景，以及支持双协议栈和蓝牙芯片跨板场景等。基于标准统一接口实现，不仅清晰易懂，而且用户可灵活配置各使用模型，满足手表、手环、音箱、模组等设备。
开发者或芯片厂商可以实现一个 struct bt_driver_s 类型的变量，并为其初始化以下成员函数：
- CODE int (*open)(FAR struct bt_driver_s *btdev);
- CODE int (*send)(FAR struct bt_driver_s *btdev, enum bt_buf_type_e type, FAR void *data, size_t len);
- CODE int (*ioctl)(FAR struct bt_driver_s *btdev, int cmd, unsigned long arg);
- CODE void (*close)(FAR struct bt_driver_s *btdev);
上述成员函数的实现依赖于 HCI（Host Controller Interface） 的实际工作方式，也就是 Host 和 Controller 之间的物理总线。目前我们使用btH5类型的驱动，支持流控以及重传机制。
6.1 open 接口实现方法
6.1.1 coex 包装层：rtk_coex_open()
static int rtk_coex_open(FAR struct bt_driver_s *dev)
{
    FAR struct rtk_coex_s *priv;
    FAR struct bt_driver_s *drv;

    DEBUGASSERT(dev != NULL);

    priv = (FAR struct rtk_coex_s *)dev;
    drv = priv->drv;

    rtk_coex_init();

    return drv->open(drv);
}
实现步骤
1. 参数断言
  - DEBUGASSERT(dev != NULL);
2. 取得下层 driver 指针 drv
3. 初始化 coex 模块（资源与状态机）
  - rtk_coex_init();
4. 透传调用下层 open
  - return drv->open(drv);
rtk_coex_init() 的具体做法
- memset(btpf, 0, sizeof(*btpf));：清空所有 coex 运行态数据
- nxmutex_init(&btpf->coexlock);：初始化互斥锁
- INIT_LIST_HEAD(&btpf->conn_list);
- INIT_LIST_HEAD(&btpf->pending_cmd_list);
关键点
- coex 的锁、链表头必须在任何 send/receive 解析前准备好。
- 此处并不启动定时器；定时器由 profile 引用计数从 0→1 时启动（见 profile_conn_get()）。

---
6.1.2 HCI UART 层：bthci_open()
实现函数
- static int bthci_open(FAR struct bt_driver_s *drv)
static int bthci_open(FAR struct bt_driver_s *drv)
{
  FAR struct rtk_bt_priv_s *dev = (struct rtk_bt_priv_s *)drv;
  wlinfo("%s, id:%d", __func__, dev->id);
  return OK;
}
注意
- 固件下载、波特率切换、控制器 reset 并不在 open() 完成，而由 rtk8723FS_initialize() 创建的线程 btuart_fw_task() 完成（异步初始化）。
static int btuart_fw_task(int argc, FAR char **argv)
{
  FAR struct rtk_bt_priv_s *dev = (struct rtk_bt_priv_s *)&g_bthci_dev;
  int ret;
  uint64_t time;
  ret = file_open(&dev->filep_h5, CONFIG_BT_UART_ON_DEV_NAME, O_RDWR);
  if (ret < 0)
    {
      wlerr("fail, filep_h5 open ret:%d", ret);
      goto errout_open;
    }
  ret = hci_check_local_ver(dev);
  if (ret < 0)
    {
      wlerr("fail, hci_check_local_ver ret:%d", ret);
      goto errout_init;
    }
  ret = hci_check_local_rom_ver(dev);
  if (ret < 0)
    {
      wlerr("fail, hci_check_local_rom_ver ret:%d", ret);
      goto errout_init;
    }
  ret = hci_update_baudrate(dev);
  if (ret < 0)
    {
      wlerr("fail, hci_update_baudrate ret:%d", ret);
      goto errout_init;
    }
  time = get_timestamp_us();
  ret = hci_load_firmware(dev);
  rtkbt_free_fwc_buf();
  if (ret < 0)
    {
      wlerr("fail, hci_load_firmware ret:%d", ret);
      goto errout_init;
    }
  wlwarn("bt download fw takes:%lld us", get_timestamp_us() - time);
  ret = hci_reset(dev);
  if (ret < 0)
    {
      wlerr("fail, hci_reset ret:%d", ret);
      goto errout_init;
    }
  ret = hci_read_local_addr(dev);
  wlerr("%s", "after hci_read_local_addr");
  if (ret < 0)
    {
      wlerr("fail, hci_read_local_addr ret:%d", ret);
      goto errout_init;
    }

  file_close(&dev->filep_h5);
  dev->state = RTKHCI_STATE_OPENNED;
  return ret;
errout_init:
  file_close(&dev->filep_h5);
errout_open:
  dev->state = RTKHCI_STATE_CLOSED;
  rtkbt_board_poweroff();
  file_close(&dev->filep_uart);
  return ret;
}

