    sbus->sdio_dev           = dev;
  /* Attach and prepare SDIO interrupts */
    SDIO_ATTACH(sbus->sdio_dev);
  /* Set ID mode clocking (<400KHz) */

  SDIO_CLOCK(dev, CLOCK_IDMODE);

  ret = sdio_probe(dev);
    if (ret != OK)
    {
    DBG_INFO("sdio_probe fail ret:%d \n",ret);
      goto exit_error;
