    {
    DBG_INFO("sdio_enable_function fail,ret=%d\n",ret);
      goto exit_error;
    }
  sbus->func.num = 1;
  /* probe WiFi driver */
  WiFi_sdio_func = &sbus->func;

exit_error:
  if (ret<0)
    DBG_INFO("ERROR: failed to probe device \n");

  return ret;
